import React from 'https://cdn.jsdelivr.net/npm/react@18.2.0/+esm'
import reactDom from 'https://cdn.jsdelivr.net/npm/react-dom@18.2.0/+esm'

function TableauDashboard() {
  const iframeRef = React.useRef(null);
  const [error, setError] = React.useState(null);

  React.useEffect(() => {
    const loadTableau = async () => {
      try {
        const embedUrl = await appsmith.store.TableauAuth.generateEmbedHtml();
        console.log('Generated Embed URL:', embedUrl);

        if (iframeRef.current) {
          iframeRef.current.src = embedUrl;
        }
      } catch (err) {
        console.error('Error loading Tableau:', err);
        setError(err.message);
      }
    };

    loadTableau();

    // Cleanup function to revoke blob URL
    return () => {
      if (iframeRef.current?.src.startsWith('blob:')) {
        URL.revokeObjectURL(iframeRef.current.src);
      }
    };
  }, []);

  if (error) {
    return <div style={{ color: 'red', padding: '20px' }}>Error: {error}</div>;
  }

  return (
    <iframe
      ref={iframeRef}
      style={{
        width: '100%',
        height: '800px',
        border: 'none'
      }}
      sandbox="allow-scripts allow-same-origin allow-popups allow-popups-to-escape-sandbox"
      allowFullScreen
    />
  );
}

appsmith.onReady(() => {
  reactDom.render(<TableauDashboard />, document.getElementById("root"));
});
